<?php if($pages > 1): ?><nav class="pagination" aria-label="Pagination"><?php for($n=max(1,$page-2);$n<=min($pages,$page+2);$n++): ?><?php if($n === $page): ?><span class="current" aria-current="page"><?= $n ?></span><?php else: ?><a href="<?= e($paginationUrl . '?' . http_build_query(array_merge($paginationParams ?? [],['page'=>$n]))) ?>"><?= $n ?></a><?php endif ?><?php endfor ?></nav><?php endif ?>
